using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// WTHS REFL and RDIF are Reflection objects: parent, clouds, sub-weathers and the other form pointers are FormLinks.
// A whole record from Starfield.esm, both readers, written back byte for byte.
public class WeatherSettingReflectionTests
{
    private static void WritesBack(IStarfieldMajorRecordGetter rec, string hex)
    {
        var written = GameConstants.Starfield.MajorRecord(Write(w => rec.WriteToBinary(w)));
        written.Content.ToArray().ShouldBe(Hex(hex));
    }

    // WeatherPartlyCloudyList (040601:Starfield.esm)
    private const string PartlyCloudyListHex = "";

    [Fact]
    public void PartlyCloudyList()
    {
        foreach (var rec in ReadBoth<IWeatherSettingGetter>(Record("WTHS", Hex(PartlyCloudyListHex)), f => WeatherSetting.CreateFromBinary(f), (s, p) => WeatherSettingBinaryOverlay.WeatherSettingFactory(s, p)))
        {
            // WeatherPartlyCloudyTemplate (0E838C), then the 20 sub-weathers Weather_PartlyCloudy_C1_Clear (02B544) to
            // Weather_PartlyCloudy_C5_MistLight (0C3047), then CloudsPartlyCloudy03 (0B7903), all Starfield.esm
            rec.ReflectionDiff.ShouldHaveFormIds(0x0E838C,
                0x02B544, 0x02B548, 0x02B54C, 0x02B550, 0x02B554, 0x02B559, 0x02B55D, 0x02B561, 0x02B565, 0x02B569,
                0x02B56D, 0x0AE7D6, 0x0AE7D7, 0x0C3041, 0x0C3042, 0x0C3043, 0x0C3044, 0x0C3045, 0x0C3046, 0x0C3047,
                0x0B7903);
            rec.ReflectionDiff.RootObject().Class.Name.ShouldBe("BGSWeatherSettingsForm");
            WritesBack(rec, PartlyCloudyListHex);
        }
    }

}
